import 'package:flutter/material.dart';

class AppBackground extends StatelessWidget {
  final Widget child;
  const AppBackground({super.key, required this.child});

  @override
  Widget build(BuildContext context) => Container(color: Colors.white, child: child);
}

class OrderPricingService {
  double calculateTotal(List<double> itemPrices, {double discountPercent = 0}) {
    if (itemPrices.isEmpty) return 0;
    final subtotal = itemPrices.reduce((a, b) => a + b);
    return subtotal * (1 - discountPercent / 100);
  }
}
